// Evolution ayarları: Railway kurulumundan sonra doldurun
const EVOLUTION_URL = 'https://EVOLUTION-ADRESI.up.railway.app';
const EVOLUTION_INSTANCE = 'vetray';

const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  if (b.event !== 'messages.upsert') continue;
  if (b.instance && b.instance !== EVOLUTION_INSTANCE) continue;
  const d = b.data ?? {};
  const k = d.key ?? {};
  let jid = k.remoteJid ?? '';
  if (jid.endsWith('@lid')) jid = k.remoteJidAlt ?? k.senderPn ?? d.senderPn ?? '';
  // Yalnızca birebir sohbetler: grup, durum ve kanal mesajları atlanır
  if (!jid.endsWith('@s.whatsapp.net')) continue;
  const m = d.message ?? {};
  const text = m.conversation ?? m.extendedTextMessage?.text ?? m.imageMessage?.caption ?? m.videoMessage?.caption ?? m.documentMessage?.caption ?? '';
  out.push({ json: {
    wa_number: jid.split('@')[0],
    name: k.fromMe ? '' : (d.pushName ?? ''),
    text,
    wa_message_id: k.id ?? '',
    from_me: Boolean(k.fromMe),
    evolution_url: EVOLUTION_URL.replace(/\/$/, ''),
    evolution_instance: EVOLUTION_INSTANCE,
  } });
}
return out;

const r = $json;

// Ardışık aynı roldeki mesajları birleştir, ilk mesaj müşteriden olsun
const messages = [];
for (const h of r.history ?? []) {
  if (!h.content) continue;
  const last = messages[messages.length - 1];
  if (last && last.role === h.role) last.content += '\n' + h.content;
  else messages.push({ role: h.role, content: h.content });
}
while (messages.length && messages[0].role !== 'user') messages.shift();

const system = [
  'Siz Vetray adına WhatsApp üzerinden gelen mesajlara cevap veren asistansınız.',
  'Her zaman resmi ve kibar konuşun, Türkçede "siz" dili kullanın. Müşteri İngilizce yazarsa kibar ve resmi İngilizce ile cevap verin. Kısa ve net yazın, WhatsApp mesajı uzunluğunda.',
  'Yalnızca aşağıdaki işletme bilgisine dayanın. Bilmediğiniz fiyat, tarih veya taahhüt uydurmayın; bu durumda ekibin dönüş yapacağını söyleyin.',
  'Müşteri bir kişiyle görüşmek isterse, teklif, sözleşme veya ödeme konusuna geçerse, şikayet ederse ya da cevap işletme bilgisinde yoksa handoff alanını true yapın ve ekibin kısa sürede dönüş yapacağını yazın.',
  r.system_prompt ? 'Konuşma tarzı:\n' + r.system_prompt : '',
  'İşletme bilgisi:\n' + (r.business_info || '(henüz girilmedi)'),
].filter(Boolean).join('\n\n');

return [{ json: {
  conversation_id: r.conversation_id,
  wa_number: r.wa_number,
  body: {
    model: 'claude-opus-5-5',
    max_tokens: 4000,
    fallbacks: 'default',
    output_config: {
      effort: 'low',
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: { reply: { type: 'string' }, handoff: { type: 'boolean' } },
          required: ['reply', 'handoff'],
          additionalProperties: false,
        },
      },
    },
    system,
    messages,
  },
} }];

const res = $json;
const prev = $('İstemi Hazırla').first().json;
const fallback = { reply: 'Mesajınız için teşekkür ederiz. Ekibimiz en kısa sürede size dönüş yapacaktır.', handoff: true };

let parsed = fallback;
if (res.stop_reason !== 'refusal') {
  const textBlock = (res.content ?? []).filter((c) => c.type === 'text').pop();
  try {
    const p = JSON.parse(textBlock?.text ?? '');
    if (typeof p.reply === 'string' && p.reply.trim()) parsed = { reply: p.reply.trim(), handoff: Boolean(p.handoff) };
  } catch (e) {}
}

return [{ json: { conversation_id: prev.conversation_id, wa_number: prev.wa_number, reply: parsed.reply, handoff: parsed.handoff } }];
